1. import * as path from 'path';
2. import * as fs from 'fs';
3. import { promisify } from 'util';
4. import { UmzugStorage, JSONStorage, verifyUmzugStorage } from './storage';
5. import * as templates from './templates';
6. import * as glob from 'glob';
7. import { CommandLineParserOptions, UmzugCLI } from './cli';
8. import * as emittery from 'emittery';
9. import * as VError from 'verror';
10. import {
11. 	InputMigrations,
12. 	MigrateDownOptions,
13. 	MigrateUpOptions,
14. 	MigrationMeta,
15. 	MigrationParams,
16. 	Promisable,
17. 	RerunBehavior,
18. 	Resolver,
19. 	RunnableMigration,
20. 	UmzugEvents,
21. 	UmzugOptions,
22. } from './types';
23. 
24. const globAsync = promisify(glob);
25. 
26. interface MigrationErrorParams extends MigrationParams<unknown> {
27. 	direction: 'up' | 'down';
28. }
29. 
30. export class Rethrowable extends VError {
31. 	static wrap(throwable: unknown): VError {
32. 		if (throwable instanceof VError) {
33. 			return throwable;
34. 		}
35. 
36. 		if (throwable instanceof Error) {
37. 			return new VError(throwable, 'Original error');
38. 		}
39. 
40. 		return new VError(
41. 			{
42. 				info: { original: throwable },
43. 			},
44. 			`Non-error value thrown. See info for full props: %s`,
45. 			throwable
46. 		);
47. 	}
48. }
49. 
50. export class MigrationError extends VError {
51. 	constructor(migration: MigrationErrorParams, original: unknown) {
52. 		super(
53. 			{
54. 				cause: Rethrowable.wrap(original),
55. 				name: 'MigrationError',
56. 				info: migration,
57. 			},
58. 			'Migration %s (%s) failed',
59. 			migration.name,
60. 			migration.direction
61. 		);
62. 	}
63. }
64. 
65. export class Umzug<Ctx extends object = object> extends emittery.Typed<UmzugEvents<Ctx>> {
66. 	private readonly storage: UmzugStorage<Ctx>;
67. 	/** @internal */
68. 	readonly migrations: (ctx: Ctx) => Promise<ReadonlyArray<RunnableMigration<Ctx>>>;
69. 
70. 	/**
71. 	 * Compile-time only property for type inference. After creating an Umzug instance, it can be used as type alias for
72. 	 * a user-defined migration. The function receives a migration name, path and the context for an umzug instance
73. 	 * @example
74. 	 * ```
75. 	 * // migrator.ts
76. 	 * import { Umzug } from 'umzug'
77. 	 *
78. 	 * const umzug = new Umzug({...})
79. 	 * export type Migration = typeof umzug._types.migration;
80. 	 *
81. 	 * umzug.up();
82. 	 * ```
83. 	 * ___
84. 	 *
85. 	 * ```
86. 	 * // migration-1.ts
87. 	 * import type { Migration } from '../migrator'
88. 	 *
89. 	 * // name and context will now be strongly-typed
90. 	 * export const up: Migration = ({name, context}) => context.query(...)
91. 	 * export const down: Migration = ({name, context}) => context.query(...)
92. 	 * ```
93. 	 */
94. 	declare readonly _types: {
95. 		migration: (params: MigrationParams<Ctx>) => Promise<unknown>;
96. 	};
97. 
98. 	/** creates a new Umzug instance */
99. 	constructor(
100. 		/** @internal */
101. 		readonly options: UmzugOptions<Ctx>
102. 	) {
103. 		super();
104. 
105. 		this.storage = verifyUmzugStorage(options.storage ?? new JSONStorage());
106. 		this.migrations = this.getMigrationsResolver(this.options.migrations);
107. 	}
108. 
109. 	private logging(message: Record<string, unknown>) {
110. 		this.options.logger?.info(message);
111. 	}
112. 
113. 	static defaultResolver: Resolver<unknown> = ({ name, path: filepath }) => {
114. 		if (!filepath) {
115. 			throw new Error(`Can't use default resolver for non-filesystem migrations`);
116. 		}
117. 
118. 		const ext = path.extname(filepath);
119. 		const canRequire = ext === '.js' || ext === '.cjs' || ext === '.ts';
120. 		const languageSpecificHelp: Record<string, string> = {
121. 			'.ts':
122. 				"TypeScript files can be required by adding `ts-node` as a dependency and calling `require('ts-node/register')` at the program entrypoint before running migrations.",
123. 			'.sql': 'Try writing a resolver which reads file content and executes it as a sql query.',
124. 		};
125. 		if (!canRequire) {
126. 			const errorParts = [
127. 				`No resolver specified for file ${filepath}.`,
128. 				languageSpecificHelp[ext],
129. 				`See docs for guidance on how to write a custom resolver.`,
130. 			];
131. 			throw new Error(errorParts.filter(Boolean).join(' '));
132. 		}
133. 
134. 		const getModule = () => {
135. 			try {
136. 				return require(filepath);
137. 			} catch (e: unknown) {
138. 				if (e instanceof SyntaxError && filepath.endsWith('.ts')) {
139. 					e.message += '\n\n' + languageSpecificHelp['.ts'];
140. 				}
141. 
142. 				throw e;
143. 			}
144. 		};
145. 
146. 		return {
147. 			name,
148. 			path: filepath,
149. 			up: async ({ context }) => getModule().up({ path: filepath, name, context }) as unknown,
150. 			down: async ({ context }) => getModule().down({ path: filepath, name, context }) as unknown,
151. 		};
152. 	};
153. 
154. 	/**
155. 	 * Get an UmzugCLI instance. This can be overriden in a subclass to add/remove commands - only use if you really know you need this,
156. 	 * and are OK to learn about/interact with the API of @rushstack/ts-command-line.
157. 	 */
158. 	protected getCli(options?: CommandLineParserOptions): UmzugCLI {
159. 		return new UmzugCLI(this, options);
160. 	}
161. 
162. 	/**
163. 	 * 'Run' an umzug instance as a CLI. This will read `process.argv`, execute commands based on that, and call
164. 	 * `process.exit` after running. If that isn't what you want, stick to the programmatic API.
165. 	 * You probably want to run only if a file is executed as the process's 'main' module with something like:
166. 	 * @example
167. 	 * if (require.main === module) {
168. 	 *   myUmzugInstance.runAsCLI()
169. 	 * }
170. 	 */
171. 	async runAsCLI(argv?: string[]): Promise<boolean> {
172. 		const cli = this.getCli();
173. 		return cli.execute(argv);
174. 	}
175. 
176. 	/**
177. 	 * create a clone of the current Umzug instance, allowing customising the list of migrations.
178. 	 * This could be used, for example, to sort the list of migrations in a specific order.
179. 	 */
180. 	extend(
181. 		transform: (migrations: ReadonlyArray<RunnableMigration<Ctx>>) => Promisable<Array<RunnableMigration<Ctx>>>
182. 	): Umzug<Ctx> {
183. 		return new Umzug({
184. 			...this.options,
185. 			migrations: async context => {
186. 				const migrations = await this.migrations(context);
187. 				return transform(migrations);
188. 			},
189. 		});
190. 	}
191. 
192. 	/** Get the list of migrations which have already been applied */
193. 	async executed(): Promise<MigrationMeta[]> {
194. 		return this.runCommand('executed', async ({ context }) => {
195. 			const list = await this._executed(context);
196. 			// We do the following to not expose the `up` and `down` functions to the user
197. 			return list.map(m => ({ name: m.name, path: m.path }));
198. 		});
199. 	}
200. 
201. 	/** Get the list of migrations which have already been applied */
202. 	private async _executed(context: Ctx): Promise<ReadonlyArray<RunnableMigration<Ctx>>> {
203. 		const [migrations, executedNames] = await Promise.all([
204. 			this.migrations(context),
205. 			this.storage.executed({ context }),
206. 		]);
207. 		const executedSet = new Set(executedNames);
208. 		return migrations.filter(m => executedSet.has(m.name));
209. 	}
210. 
211. 	/** Get the list of migrations which are yet to be applied */
212. 	async pending(): Promise<MigrationMeta[]> {
213. 		return this.runCommand('pending', async ({ context }) => {
214. 			const list = await this._pending(context);
215. 			// We do the following to not expose the `up` and `down` functions to the user
216. 			return list.map(m => ({ name: m.name, path: m.path }));
217. 		});
218. 	}
219. 
220. 	private async _pending(context: Ctx): Promise<Array<RunnableMigration<Ctx>>> {
221. 		const [migrations, executedNames] = await Promise.all([
222. 			this.migrations(context),
223. 			this.storage.executed({ context }),
224. 		]);
225. 		const executedSet = new Set(executedNames);
226. 		return migrations.filter(m => !executedSet.has(m.name));
227. 	}
228. 
229. 	protected async runCommand<T>(command: string, cb: (commandParams: { context: Ctx }) => Promise<T>): Promise<T> {
230. 		const context: Ctx =
231. 			typeof this.options.context === 'function'
232. 				? (this.options.context as () => Ctx)()
233. 				: ((this.options.context ?? {}) as Ctx);
234. 
235. 		await this.emit('beforeCommand', { command, context });
236. 		try {
237. 			return await cb({ context });
238. 		} finally {
239. 			await this.emit('afterCommand', { command, context });
240. 		}

