1. import { UmzugStorage } from './storage';
2. import * as typeFest from 'type-fest';
3. 
4. /**
5.  * Create a type that has mutually exclusive keys.
6.  * Wrapper for @see `import('type-fest').MergeExclusive` that works for three types
7.  */
8. export type MergeExclusive<A, B, C> = typeFest.MergeExclusive<A, typeFest.MergeExclusive<B, C>>;
9. 
10. export type Promisable<T> = T | PromiseLike<T>;
11. 
12. export type LogFn = (message: Record<string, unknown>) => void;
13. 
14. /** Constructor options for the Umzug class */
15. export interface UmzugOptions<Ctx extends {} = Record<string, unknown>> {
16. 	/** The migrations that the Umzug instance should perform */
17. 	migrations: InputMigrations<Ctx>;
18. 	/** A logging function. Pass `console` to use stdout, or pass in your own logger. Pass `undefined` explicitly to disable logging. */
19. 	logger: Record<'info' | 'warn' | 'error' | 'debug', LogFn> | undefined;
20. 	/** The storage implementation. By default, `JSONStorage` will be used */
21. 	storage?: UmzugStorage<Ctx>;
22. 	/** An optional context object, which will be passed to each migration function, if defined */
23. 	context?: Ctx | (() => Ctx);
24. 	/** Options for file creation */
25. 	create?: {
26. 		/**
27. 		 * A function for generating placeholder migration files. Specify to make sure files generated via CLI or using `.create` follow team conventions.
28. 		 * Should return an array of [filepath, content] pairs. Usually, only one pair is needed, but to put `down` migrations in a separate
29. 		 * file, more than one can be returned.
30. 		 */
31. 		template?: (filepath: string) => Array<[string, string]>;
32. 		/**
33. 		 * The default folder that new migration files should be generated in. If this is not specified, the new migration file will be created
34. 		 * in the same folder as the last existing migration. The value here can be overriden by passing `folder` when calling `create`.
35. 		 */
36. 		folder?: string;
37. 	};
38. }
39. 
40. /** Serializeable metadata for a migration. The structure returned by the external-facing `pending()` and `executed()` methods. */
41. export interface MigrationMeta {
42. 	/** Name - this is used as the migration unique identifier within storage */
43. 	name: string;
44. 	/** An optional filepath for the migration. Note: this may be undefined, since not all migrations correspond to files on the filesystem */
45. 	path?: string;
46. }
47. 
48. export interface MigrationParams<T> {
49. 	name: string;
50. 	path?: string;
51. 	context: T;
52. }
53. 
54. /** A callable function for applying or reverting a migration  */
55. export type MigrationFn<T = unknown> = (params: MigrationParams<T>) => Promise<unknown>;
56. 
57. /**
58.  * A runnable migration. Represents a migration object with an `up` function which can be called directly, with no arguments, and an optional `down` function to revert it.
59.  */
60. export interface RunnableMigration<T> extends MigrationMeta {
61. 	/** The effect of applying the migration */
62. 	up: MigrationFn<T>;
63. 	/** The effect of reverting the migration */
64. 	down?: MigrationFn<T>;
65. }
66. 
67. /** Glob instructions for migration files */
68. export type GlobInputMigrations<T> = {
69. 	/**
70. 	 * A glob string for migration files. Can also be in the format `[path/to/migrations/*.js', {cwd: 'some/base/dir', ignore: '**ignoreme.js' }]`
71. 	 * See https://npmjs.com/package/glob for more details on the glob format - this package is used internally.
72. 	 */
73. 	glob: string | [string, { cwd?: string; ignore?: string | string[] }];
74. 	/** Will be supplied to every migration function. Can be a database client, for example */
75. 	/** A function which takes a migration name, path and context, and returns an object with `up` and `down` functions. */
76. 	resolve?: Resolver<T>;
77. };
78. 
79. /**
80.  * Allowable inputs for migrations. Can be either glob instructions for migration files, a list of runnable migrations, or a
81.  * function which receives a context and returns a list of migrations.
82.  */
83. export type InputMigrations<T> =
84. 	| GlobInputMigrations<T>
85. 	| Array<RunnableMigration<T>>
86. 	| ((context: T) => Promisable<InputMigrations<T>>);
87. 
88. /** A function which takes a migration name, path and context, and returns an object with `up` and `down` functions. */
89. export type Resolver<T> = (params: MigrationParams<T>) => RunnableMigration<T>;
90. 
91. export const RerunBehavior = {
92. 	/** Hard error if an up migration that has already been run, or a down migration that hasn't, is encountered */
93. 	THROW: 'THROW',
94. 	/** Silently skip up migrations that have already been run, or down migrations that haven't */
95. 	SKIP: 'SKIP',
96. 	/** Re-run up migrations that have already been run, or down migrations that haven't */
97. 	ALLOW: 'ALLOW',
98. } as const;
99. 
100. export type RerunBehavior = keyof typeof RerunBehavior;
101. 
102. export type MigrateUpOptions = MergeExclusive<
103. 	{
104. 		/** If specified, migrations up to and including this name will be run. Otherwise, all pending migrations will be run */
105. 		to?: string;
106. 	},
107. 	{
108. 		/** Only run this many migrations. If not specified, all pending migrations will be run */
109. 		step: number;
110. 	},
111. 	{
112. 		/** If specified, only the migrations with these names migrations will be run. An error will be thrown if any of the names are not found in the list of available migrations */
113. 		migrations: string[];
114. 
115. 		/** What to do if a migration that has already been run is explicitly specified. Default is `THROW`. */
116. 		rerun?: RerunBehavior;
117. 	}
118. >;
119. 
120. export type MigrateDownOptions = MergeExclusive<
121. 	{
122. 		/** If specified, migrations down to and including this name will be revert. Otherwise, only the last executed will be reverted */
123. 		to?: string | 0;
124. 	},
125. 	{
126. 		/** Revert this many migrations. If not specified, only the most recent migration will be reverted */
127. 		step: number;
128. 	},
129. 	{
130. 		/**
131. 		 * If specified, only the migrations with these names migrations will be reverted. An error will be thrown if any of the names are not found in the list of executed migrations.
132. 		 * Note, migrations will be run in the order specified.
133. 		 */
134. 		migrations: string[];
135. 
136. 		/** What to do if a migration that has not been run is explicitly specified. Default is `THROW`. */
137. 		rerun?: RerunBehavior;
138. 	}
139. >;
140. 
141. /** Map of eventName -> eventData type, where the keys are the string events that are emitted by an umzug instances, and the values are the payload emitted with the corresponding event. */
142. export interface UmzugEvents<Ctx> {
143. 	migrating: MigrationParams<Ctx>;
144. 	migrated: MigrationParams<Ctx>;
145. 	reverting: MigrationParams<Ctx>;
146. 	reverted: MigrationParams<Ctx>;
147. 	beforeCommand: { command: string; context: Ctx };
148. 	afterCommand: { command: string; context: Ctx };
149. }
150.

